CREATE TABLE IF NOT EXISTS family_members(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,relationship VARCHAR(40) NOT NULL,birth_date DATE NULL,active TINYINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX family_owner(user_id,active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payment_intents(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT UNSIGNED NOT NULL UNIQUE,amount_toman INT UNSIGNED NOT NULL,authority VARCHAR(64) NULL UNIQUE,merchant_id VARCHAR(36) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',reference VARCHAR(100) NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,verified_at DATETIME NULL,FOREIGN KEY(booking_id) REFERENCES bookings(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO settings (`key`,value) VALUES('booking_fee','0'),('booking_fee_enabled','0'),('hold_minutes','10'),('max_active_bookings','5'),('patient_cancel_hours','24'),('patient_move_hours','24'),('patient_cancel_enabled','1'),('patient_move_enabled','1');
